def module_path(path: str) ->Tuple[str, Optional[str]]:
    if ':' in path:
        module, qualname = path.split(':', 1)
        if '/' in module or (module.endswith('.py')):
            raise argparse.ArgumentTypeError(
                f"{module} does not look like a valid Python import path"
            )
        return module, qualname
    if '/' in path or path.endswith('.py'):
        raise argparse.ArgumentTypeError(
            f"{path} does not look like a valid Python import path"
        )
    return path, None


def module_path_with_qualname(path: str) ->Tuple[str, str]:
    module, qualname = module_path(path)
    if qualname is None:
        raise argparse.ArgumentTypeError(
            f"Must specify a qualname for this command, e.g. {path}:MyClass.method"
        )
    return module, qualname


def get_monkeytype_config(path: str) ->Config:
    module_name, func_name = path.rsplit(':', 1)
    config = get_name_in_module(module_name, func_name)
    if not isinstance(config, Config):
        raise argparse.ArgumentTypeError(
            f"{path} is not an instance of monkeytype.config.Config"
        )
    return config


def display_sample_count(traces: List[CallTrace], stderr: IO[str]) ->None:
    counts: collections.Counter = collections.Counter()
    for trace in traces:
        counts[trace.func] += 1
    for func, count in counts.items():
        module = func.__module__
        qualname = func.__qualname__
        print(f"Annotation for {module}.{qualname} based on {count} call trace(s).", file=stderr)


def get_stub(args: argparse.Namespace, stdout: IO[str], stderr: IO[str]
    ) ->Optional[Stub]:
    module, qualname = args.module_path
    store = args.config.trace_store()
    traces = []
    failed_traces = 0
    try:
        raw_traces = store.filter(module, qualname)
        for trace in raw_traces:
            try:
                traces.append(trace)
            except MonkeyTypeError as e:
                failed_traces += 1
                if args.verbose:
                    print(f"WARNING: Failed decoding trace: {e}", file=stderr)
    except MonkeyTypeError as e:
        failed_traces += 1
        if args.verbose:
            print(f"WARNING: Failed decoding trace: {e}", file=stderr)

    if not traces and failed_traces == 0:
        return None

    if failed_traces > 0 and not args.verbose:
        print(f"{failed_traces} traces failed to decode", file=stderr)

    if not traces:
        return None

    if args.sample_count:
        display_sample_count(traces, stderr)

    rewriter = args.config.type_rewriter()
    stubs = build_module_stubs_from_traces(
        traces,
        existing_annotation_strategy=args.existing_annotation_strategy,
        rewriter=rewriter,
    )
    return stubs.get(module)


def print_stub_handler(args: argparse.Namespace, stdout: IO[str], stderr:
    IO[str]) ->None:
    if args.diff:
        diff = get_diff(args, stdout, stderr)
        if diff:
            print(diff, file=stdout)
        elif diff is None:
            complain_about_no_traces(args, stderr)
        return
    stub = get_stub(args, stdout, stderr)
    if stub is None:
        complain_about_no_traces(args, stderr)
        return
    print(stub.render(), file=stdout)


def update_args_from_config(args: argparse.Namespace) ->None:
    if not hasattr(args, 'existing_annotation_strategy'):
        if hasattr(args, 'ignore_existing_annotations') and args.ignore_existing_annotations:
            args.existing_annotation_strategy = ExistingAnnotationStrategy.IGNORE
        else:
            args.existing_annotation_strategy = ExistingAnnotationStrategy.REPLICATE
    if not hasattr(args, 'sample_count'):
        args.sample_count = False
    if not hasattr(args, 'diff'):
        args.diff = False
    if not hasattr(args, 'verbose'):
        args.verbose = False
    if not hasattr(args, 'pep_563'):
        args.pep_563 = False


def main(argv: List[str], stdout: IO[str], stderr: IO[str]) ->int:
    parser = argparse.ArgumentParser(
        description="MonkeyType: Automatically generate type annotations from runtime traces"
    )
    parser.add_argument(
        '-v', '--verbose',
        action='store_true',
        default=False,
        help='Verbose output'
    )
    parser.add_argument(
        '-c', '--config',
        type=get_monkeytype_config,
        default=None,
        help='Path to config object'
    )

    subparsers = parser.add_subparsers(title='commands')

    stub_parser = subparsers.add_parser('stub', help='Generate a stub for a module')
    stub_parser.add_argument('module_path', type=module_path, help='Module path')
    stub_parser.add_argument(
        '--ignore-existing-annotations',
        action='store_true',
        default=False,
        dest='ignore_existing_annotations',
        help='Ignore existing annotations'
    )
    stub_parser.add_argument(
        '--diff',
        action='store_true',
        default=False,
        help='Show diff'
    )
    stub_parser.add_argument(
        '--sample-count',
        action='store_true',
        default=False,
        dest='sample_count',
        help='Show sample count'
    )
    stub_parser.set_defaults(handler=print_stub_handler)

    apply_parser = subparsers.add_parser('apply', help='Apply a stub to a module')
    apply_parser.add_argument('module_path', type=module_path, help='Module path')
    apply_parser.add_argument(
        '--ignore-existing-annotations',
        action='store_true',
        default=False,
        dest='ignore_existing_annotations',
        help='Ignore existing annotations'
    )
    apply_parser.add_argument(
        '--pep-563',
        action='store_true',
        default=False,
        dest='pep_563',
        help='Use PEP 563 style annotations'
    )
    apply_parser.set_defaults(handler=apply_stub_handler)

    list_modules_parser = subparsers.add_parser('list-modules', help='List modules with traces')
    list_modules_parser.set_defaults(handler=list_modules_handler)

    run_parser = subparsers.add_parser('run', help='Run a script with tracing')
    run_parser.add_argument('-m', action='store_true', default=False, help='Run as module')
    run_parser.add_argument('script_path', help='Script path')
    run_parser.add_argument('script_args', nargs=argparse.REMAINDER, help='Script arguments')
    run_parser.set_defaults(handler=run_handler)

    args = parser.parse_args(argv)

    if not hasattr(args, 'handler'):
        parser.print_help(stderr)
        return 1

    if args.config is None:
        from monkeytype.config import DefaultConfig
        args.config = DefaultConfig()

    update_args_from_config(args)

    ctx = args.config.cli_context(args.handler.__name__.replace('_handler', ''))
    with ctx:
        args.handler(args, stdout, stderr)

    return 0
